CREATE MEMORY TABLE "PUBLIC"."ESTANCIAS"(
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY(START WITH 1 RESTART WITH 9) NOT NULL,
    "ACTIVA" BOOLEAN NOT NULL,
    "FECHA_HORA_ENTRADA" TIMESTAMP(6) NOT NULL,
    "FECHA_HORA_SALIDA" TIMESTAMP(6),
    "MINUTOS_TRANSCURRIDOS" BIGINT,
    "MONTO_COBRADO" NUMERIC(38, 2),
    "PLACA" CHARACTER VARYING(255) NOT NULL
);         
